CREATE TABLE projects(id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('public','private')), created_at INTEGER NOT NULL DEFAULT(unixepoch()));
CREATE TABLE runtimes(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), name TEXT NOT NULL, slug TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'inherit' CHECK(visibility IN ('inherit','private','public')), sync_interval INTEGER NOT NULL DEFAULT 3600 CHECK(sync_interval>=60), last_checked INTEGER, last_success INTEGER, active_publication INTEGER REFERENCES publications(id), UNIQUE(project_id,slug));
CREATE TABLE sources(id INTEGER PRIMARY KEY, runtime_id INTEGER NOT NULL REFERENCES runtimes(id), kind TEXT NOT NULL CHECK(kind IN ('url','upload')), url TEXT, upload BLOB, mapping TEXT, etag TEXT, last_modified TEXT, last_checked INTEGER, last_success INTEGER, status TEXT NOT NULL DEFAULT 'pending', error TEXT);
CREATE TABLE jobs(id INTEGER PRIMARY KEY, runtime_id INTEGER NOT NULL REFERENCES runtimes(id), state TEXT NOT NULL DEFAULT 'queued', created_at INTEGER NOT NULL DEFAULT(unixepoch()), finished_at INTEGER, error TEXT);
CREATE UNIQUE INDEX one_live_job ON jobs(runtime_id) WHERE state IN ('queued','running');
CREATE TABLE publications(id INTEGER PRIMARY KEY, runtime_id INTEGER NOT NULL REFERENCES runtimes(id), created_at INTEGER NOT NULL DEFAULT(unixepoch()), manifest TEXT NOT NULL, upstream TEXT);
CREATE TABLE files(id INTEGER PRIMARY KEY, publication_id INTEGER NOT NULL REFERENCES publications(id), release TEXT NOT NULL, filename TEXT NOT NULL, digest TEXT NOT NULL, size INTEGER NOT NULL, source_url TEXT NOT NULL, UNIQUE(publication_id,release,filename));
CREATE INDEX file_digest ON files(digest);
CREATE TABLE transfers(id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL REFERENCES jobs(id), runtime_id INTEGER NOT NULL REFERENCES runtimes(id), filename TEXT NOT NULL, host TEXT NOT NULL, backend TEXT NOT NULL, state TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, total INTEGER, speed REAL, retries INTEGER NOT NULL DEFAULT 0, retry_at INTEGER, error TEXT, command TEXT);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1), engine TEXT NOT NULL DEFAULT 'native', concurrency INTEGER NOT NULL DEFAULT 4, per_host INTEGER NOT NULL DEFAULT 2, retries INTEGER NOT NULL DEFAULT 3, sync_interval INTEGER NOT NULL DEFAULT 3600);
